const resposta = ($json.answer || '').trim();
const texto = resposta.replace(/\*\*(.*?)\*\*/g, '*$1*');
const blocos = texto.split(/\n\s*\n/).map(p => p.trim()).filter(p => p.length > 0);
const partes = [];
for (const b of blocos) {
  if (partes.length && b.length < 40) { partes[partes.length - 1] += '\n' + b; }
  else { partes.push(b); }
}
return [{ json: { responses: partes.length ? partes : [texto] } }];
